  insert into parlons_expansion_bank (draft_id, theme_key, language_code, text) values
    ('EL01', 'everyday-life', 'en', 'Which cheap object would you be most annoyed to lose? Explain why replacing it would not be quite the same.'),
    ('EL01', 'everyday-life', 'fr', 'Quel objet peu coûteux seriez-vous le plus contrarié de perdre ? Pourquoi son remplacement ne serait-il pas tout à fait pareil ?'),
    ('EL02', 'everyday-life', 'en', 'You can make one everyday item twice as big or half its size. What do you change, and who benefits?'),
    ('EL02', 'everyday-life', 'fr', 'Vous pouvez doubler la taille d''un objet du quotidien ou la réduire de moitié. Que changez-vous, et à qui cela profite-t-il ?'),
    ('EL03', 'everyday-life', 'en', 'Give a passionate defence of a food combination other people find strange.'),
    ('EL03', 'everyday-life', 'fr', 'Défendez avec passion une association d''aliments que les autres trouvent étrange.'),
    ('EL04', 'everyday-life', 'en', 'Two people share a kitchen: one cleans while cooking, the other cleans afterward. Negotiate an arrangement they can both live with.'),
    ('EL04', 'everyday-life', 'fr', 'Deux personnes partagent une cuisine : l''une nettoie en cuisinant, l''autre après. Négociez un arrangement qui leur convient à toutes les deux.'),
    ('EL05', 'everyday-life', 'en', 'Which everyday task looks easy until you have to explain every step to a beginner?'),
    ('EL05', 'everyday-life', 'fr', 'Quelle tâche quotidienne semble facile jusqu''au moment où il faut en expliquer chaque étape à un débutant ?'),
    ('EL06', 'everyday-life', 'en', 'Your electricity will be off for an evening, with enough notice to prepare. Plan an evening you might actually enjoy.'),
    ('EL06', 'everyday-life', 'fr', 'Une coupure de courant est prévue pour toute une soirée. Vous avez le temps de vous préparer. Imaginez une soirée qui pourrait vous plaire malgré tout.'),
    ('EL07', 'everyday-life', 'en', 'A visitor can observe your home but cannot ask questions. What might they wrongly conclude about you?'),
    ('EL07', 'everyday-life', 'fr', 'Une personne peut observer votre logement, mais ne peut pas vous poser de questions. Que pourrait-elle en déduire à tort sur vous ?'),
    ('EL08', 'everyday-life', 'en', 'A shopping list says: lemons, string, a birthday candle, batteries and a single potato. Who wrote it, and what are they planning?'),
    ('EL08', 'everyday-life', 'fr', 'Une liste de courses indique : des citrons, de la ficelle, une bougie d''anniversaire, des piles et une seule pomme de terre. Qui l''a écrite, et que prépare cette personne ?'),
    ('EL09', 'everyday-life', 'en', 'Which item do people buy for the person they hope to become? Explain what happens when it gets home.'),
    ('EL09', 'everyday-life', 'fr', 'Quel objet achète-t-on pour la personne qu''on espère devenir ? Racontez ce qui se passe une fois l''objet à la maison.'),
    ('EL10', 'everyday-life', 'en', 'You are leaving instructions for someone looking after your home. What detail would be obvious to you but surprising to them?'),
    ('EL10', 'everyday-life', 'fr', 'Vous laissez des consignes à quelqu''un qui va s''occuper de votre logement. Quel détail évident pour vous pourrait le surprendre ?'),
    ('RE01', 'relationships', 'en', 'A friend asks for your opinion but seems to want encouragement. How would you work out what they need?'),
    ('RE01', 'relationships', 'fr', 'Un ami vous demande votre avis, mais semble surtout chercher des encouragements. Comment savoir ce dont il a besoin ?'),
    ('RE02', 'relationships', 'en', 'Two friends remember the same event very differently. Does either of them need to win the argument?'),
    ('RE02', 'relationships', 'fr', 'Deux amis ont des souvenirs très différents d''un même événement. Faut-il forcément que l''un des deux ait raison ?'),
    ('RE03', 'relationships', 'en', 'You receive a generous invitation to something you would hate. Decline it without making the host regret asking.'),
    ('RE03', 'relationships', 'fr', 'On vous invite généreusement à une activité qui ne vous plairait pas du tout. Déclinez sans faire regretter à la personne de vous avoir invité.'),
    ('RE04', 'relationships', 'en', 'Someone keeps giving you advice you did not request. What could you say while keeping the relationship warm?'),
    ('RE04', 'relationships', 'fr', 'Quelqu''un vous donne sans cesse des conseils que vous n''avez pas demandés. Que pourriez-vous dire sans refroidir la relation ?'),
    ('RE05', 'relationships', 'en', 'Can a friendship work when one person loves debating and the other finds disagreement exhausting?'),
    ('RE05', 'relationships', 'fr', 'Une amitié peut-elle fonctionner quand l''un adore débattre et que l''autre trouve les désaccords épuisants ?'),
    ('RE06', 'relationships', 'en', 'You are introducing two friends who have almost nothing in common. How would you get their conversation started?'),
    ('RE06', 'relationships', 'fr', 'Vous présentez deux amis qui n''ont presque rien en commun. Comment lanceriez-vous la conversation entre eux ?'),
    ('RE07', 'relationships', 'en', 'What kind of compliment is hardest to forget? Give a real or invented example.'),
    ('RE07', 'relationships', 'fr', 'Quel genre de compliment est le plus difficile à oublier ? Donnez un exemple réel ou inventé.'),
    ('RE08', 'relationships', 'en', 'A group chat has gone quiet. Should someone revive it, or can it end naturally?'),
    ('RE08', 'relationships', 'fr', 'Une conversation de groupe ne reçoit plus de messages. Faut-il la relancer ou la laisser s''éteindre naturellement ?'),
    ('RE09', 'relationships', 'en', 'You lend something to a friend and it comes back damaged. What matters most in the conversation that follows?'),
    ('RE09', 'relationships', 'fr', 'Vous prêtez un objet à un ami, qui vous le rend abîmé. Qu''est-ce qui compte le plus dans la conversation qui suit ?'),
    ('RE10', 'relationships', 'en', 'Is it better to ask someone how they want to be supported or to take the initiative? Describe when each approach helps.'),
    ('RE10', 'relationships', 'fr', 'Vaut-il mieux demander à quelqu''un comment le soutenir ou prendre les devants ? Dans quelles situations chaque approche est-elle utile ?'),
    ('CU01', 'culture', 'en', 'A film you disliked keeps coming up in conversation. Explain what it did well before explaining why it did not work for you.'),
    ('CU01', 'culture', 'fr', 'Un film que vous n''avez pas aimé revient souvent dans les conversations. Expliquez d''abord ses qualités, puis pourquoi il ne vous a pas plu.'),
    ('CU02', 'culture', 'en', 'You can hear one song again as though you have never heard it before. Which would you choose, and where would you listen?'),
    ('CU02', 'culture', 'fr', 'Vous pouvez réécouter une chanson comme si vous ne l''aviez jamais entendue. Laquelle choisissez-vous, et où l''écoutez-vous ?'),
    ('CU03', 'culture', 'en', 'Does knowing how much effort went into something change how much you enjoy it?'),
    ('CU03', 'culture', 'fr', 'Savoir combien d''efforts une création a demandés change-t-il le plaisir que vous en tirez ?'),
    ('CU05', 'culture', 'en', 'A restaurant removes your favourite dish because almost nobody orders it. Make the case for keeping it—or explain why you would accept the decision.'),
    ('CU05', 'culture', 'fr', 'Un restaurant retire votre plat préféré parce que presque personne ne le commande. Défendez son maintien ou expliquez pourquoi vous accepteriez cette décision.'),
    ('CU06', 'culture', 'en', 'What makes something feel dated in a charming way rather than an embarrassing way?'),
    ('CU06', 'culture', 'fr', 'Qu''est-ce qui donne à une œuvre un charme désuet plutôt qu''un côté embarrassant ?'),
    ('CU08', 'culture', 'en', 'Would you rather know the ending of a story in advance or know nothing at all? Explain what you gain and lose.'),
    ('CU08', 'culture', 'fr', 'Préférez-vous connaître la fin d''une histoire à l''avance ou ne rien savoir du tout ? Qu''y gagnez-vous et qu''y perdez-vous ?'),
    ('CU09', 'culture', 'en', 'A local cinema can show only one film this month. How should it choose something for a community with different tastes?'),
    ('CU09', 'culture', 'fr', 'Un cinéma de quartier ne peut projeter qu''un seul film ce mois-ci. Comment choisir pour un public aux goûts variés ?'),
    ('CU10', 'culture', 'en', 'Choose a minor character from a story you know. What would their ordinary day look like after the story ends?'),
    ('CU10', 'culture', 'fr', 'Choisissez un personnage secondaire d''une histoire que vous connaissez. À quoi ressemblerait une journée ordinaire de sa vie après la fin de l''histoire ?'),
    ('SO01', 'society', 'en', 'A busy park has space for either a quiet garden or a sports court. Present the strongest case for each before choosing.'),
    ('SO01', 'society', 'fr', 'Dans un parc très fréquenté, il reste de la place soit pour un jardin paisible, soit pour un terrain de sport. Défendez chaque option avant de choisir.'),
    ('SO02', 'society', 'en', 'Should a popular free event require reservations if many people reserve and never arrive?'),
    ('SO02', 'society', 'fr', 'Un événement gratuit très populaire devrait-il imposer des réservations si beaucoup de personnes réservent sans venir ?'),
    ('SO03', 'society', 'en', 'A town wants to rename a street. Who should have a say, and what would make the process feel fair?'),
    ('SO03', 'society', 'fr', 'Une ville veut changer le nom d''une rue. Qui devrait participer à la décision, et comment rendre la démarche équitable ?'),
    ('SO04', 'society', 'en', 'What should people be allowed to do in a public square without buying anything?'),
    ('SO04', 'society', 'fr', 'Que devrait-on pouvoir faire sur une place publique sans rien acheter ?'),
    ('SO05', 'society', 'en', 'Your neighbourhood noticeboard is full of complaints. What good thing would you announce to change the mood?'),
